import {QuotaBanner} from '@github-ui/agent-sessions/components/task-view/QuotaBanner'
import {useAgentQuotaSnapshot} from '@github-ui/agent-sessions/hooks/use-agent-quota-snapshot'
import {useEffect, useState} from 'react'

import styles from './CopilotQuotaBannerPartial.module.css'

/**
 * Window event dispatched by this partial whenever the quota snapshot resolves.
 * Consumed by the catalyst `<copilot-mentions-hint>` element so it can disable
 * the comment submit button when the viewer can't start a new agent session.
 */
export const COPILOT_MENTION_QUOTA_STATUS_EVENT = 'copilot-mention-quota-status'

/**
 * Window event dispatched by the catalyst `<copilot-mentions-hint>` element
 * whenever the textarea enters or leaves @copilot / agent-mention mode. We
 * subscribe to it so that the agent-quota-snapshot fetch only fires when an
 * @copilot mention is actually present, instead of on every PR page load.
 */
export const COPILOT_MENTION_DETECTED_EVENT = 'copilot-mention-detected'

export type CopilotMentionQuotaStatusEventDetail = {
  canStartSession: boolean
}

export type CopilotMentionDetectedEventDetail = {
  detected: boolean
}

declare global {
  interface WindowEventMap {
    [COPILOT_MENTION_QUOTA_STATUS_EVENT]: CustomEvent<CopilotMentionQuotaStatusEventDetail>
    [COPILOT_MENTION_DETECTED_EVENT]: CustomEvent<CopilotMentionDetectedEventDetail>
  }
}

/**
 * React partial that surfaces a TBB quota status banner in the PR comment
 * field area (alongside `copilot-mentions-hint`). The quota snapshot is only
 * fetched when an @copilot / agent mention is detected in the textarea, so
 * the API call is proportional to actual @copilot usage rather than firing
 * on every PR page load.
 *
 * Also broadcasts a `copilot-mention-quota-status` window event so the
 * catalyst `<copilot-mentions-hint>` element can disable the submit button
 * when the viewer's quota is insufficient to start a new agent session.
 *
 * SAFETY: the banner + submit-button disable must NEVER surface unless the
 * user is actively composing an @copilot/agent mention. Two independent
 * gates enforce this invariant — both must be true for the user to see any
 * effect:
 *
 *   1. (this file) `agentQuotaSnapshot` is forced to undefined when
 *      `hasCopilotMention === false`. Returns `null` when undefined, so the
 *      banner cannot render without a mention. The dispatched
 *      `copilot-mention-quota-status` event falls back to
 *      `canStartSession: true` in that case.
 *
 *   2. (copilot-mentions-hint-element.ts, #applySubmitButtonQuotaState) the
 *      submit-button disable requires `#inCopilotMode === true`. A
 *      `canStartSession: false` event arriving without an active mention
 *      cannot disable any buttons.
 */
/**
 * Window event the partial dispatches on mount to request that
 * `<copilot-mentions-hint>` re-emit its current `copilot-mention-detected`
 * state. This handles the mount-order race where the catalyst element
 * already transitioned into mention mode before this partial loaded — the
 * partial would otherwise miss the edge-triggered event and stay stuck in
 * `hasCopilotMention === false` forever. See `#handleMentionDetectedRequest`
 * in copilot-mentions-hint-element.ts.
 */
export const COPILOT_MENTION_DETECTED_REQUEST_EVENT = 'copilot-mention-detected-request'

declare global {
  interface WindowEventMap {
    [COPILOT_MENTION_DETECTED_REQUEST_EVENT]: CustomEvent<void>
  }
}

/**
 * Reads the current mention-mode state synchronously from the DOM so we can
 * seed `hasCopilotMention` at mount time without waiting for an event. The
 * catalyst element reflects `#inCopilotMode` to a `data-in-copilot-mode`
 * attribute, so this is a stable observable signal.
 */
function readInitialMentionState(): boolean {
  if (typeof document === 'undefined') return false
  return !!document.querySelector('copilot-mentions-hint[data-in-copilot-mode]')
}

export function CopilotQuotaBannerPartial() {
  const [hasCopilotMention, setHasCopilotMention] = useState(readInitialMentionState)

  useEffect(() => {
    const handler = (event: WindowEventMap[typeof COPILOT_MENTION_DETECTED_EVENT]) => {
      setHasCopilotMention(event.detail.detected)
    }
    window.addEventListener(COPILOT_MENTION_DETECTED_EVENT, handler)
    // Belt-and-braces: even though `readInitialMentionState` seeded the
    // initial value from the DOM, dispatch a request event so any catalyst
    // element that mounts AFTER us also gets a chance to push its current
    // state back. Idempotent: the catalyst handler just re-emits the same
    // value via the listener above.
    window.dispatchEvent(new CustomEvent(COPILOT_MENTION_DETECTED_REQUEST_EVENT))
    return () => {
      window.removeEventListener(COPILOT_MENTION_DETECTED_EVENT, handler)
    }
  }, [])

  // TanStack Query keeps the last successful response in the cache even after
  // `enabled` flips back to false, so reading `data` directly would leak the
  // previous snapshot and keep the banner mounted after the user removed the
  // @copilot mention. Coerce to undefined when no mention is present so the
  // partial unmounts and the dispatched quota status falls back to "can start
  // session" — preserving the invariant that the snapshot drives the UI only
  // while the user is actively composing an @copilot/agent mention.
  const {data: cachedSnapshot} = useAgentQuotaSnapshot({enabled: hasCopilotMention})
  const agentQuotaSnapshot = hasCopilotMention ? cachedSnapshot : undefined

  // When the snapshot is unavailable we assume the viewer can start a session
  // and don't block submission — falling back to the existing behavior.
  const canStartSession = agentQuotaSnapshot?.can_start_session ?? true

  useEffect(() => {
    window.dispatchEvent(new CustomEvent(COPILOT_MENTION_QUOTA_STATUS_EVENT, {detail: {canStartSession}}))
  }, [canStartSession])

  if (!agentQuotaSnapshot) return null

  return (
    <div className={styles.commentBoxSurface}>
      <QuotaBanner agentQuotaSnapshot={agentQuotaSnapshot} />
    </div>
  )
}
